/bin/bash -lc "python - <<'PY'
import json
x=json.load(open('dnase_embedded.json'))
a=x['@graph'][0]
print(a['accession'],a['datasets'])
for f in a['files']:
 if f.get('file_format')=='bam': print(f['accession'],f['output_type'],f.get('biological_replicates'),f['file_size'])
for q in a['quality_metrics']:
 qm=q['quality_metric']
 if 'SamtoolsStatsQualityMetric' in qm.get('@type',[]): print(q['files'],q.get('biological_replicates'),qm.get('reads mapped'),qm.get('reads MQ0'),qm.get('reads duplicated'))
PY"

